#include <iostream>
#include <stdexcept>
#include <vector>

// 用 vector 当底层存储：栈只是「只能在一头进出」的数组。
class IntStack {
public:
    void push(int value) { data_.push_back(value); }

    int pop() {
        if (data_.empty()) throw std::runtime_error("栈是空的");
        const int value = data_.back();
        data_.pop_back();
        return value;
    }

    bool empty() const { return data_.empty(); }

private:
    std::vector<int> data_;
};

int main() {
    IntStack stack;
    stack.push(1);
    stack.push(2);
    stack.push(3);
    while (!stack.empty()) std::cout << stack.pop() << ' ';
    std::cout << '\n';
    try {
        stack.pop();
    } catch (const std::exception& e) {
        std::cout << "出错：" << e.what() << '\n';
    }
}

