#include <iostream>
#include <string>
#include <algorithm>
int main() {
    // 先算、再存、再更新；注释说明目的。
    int total = 2 + 3;
    total += 4;
    std::cout << total << '\n';
    // 按含义选类型，boolalpha只改变真假输出格式。
    int count = 3;
    double price = 2.5;
    bool ready = true;
    char grade = 'A';
    std::string name = "box";
    std::cout << count << ' ' << price << ' ' << std::boolalpha
              << ready << ' ' << grade << ' ' << name << '\n';
    int progress{};             // 初始化为0
    const int step = 2;
    progress = progress + step; // 已存在对象的赋值
    std::cout << progress << '\n';
    std::cout << std::max(3, 7) << ' ' << std::max(-2, -5) << '\n';
}

